/** The line-drawn Snowflake mark (the case page and loop 1's footer). */
export function SnowflakeLine() {
  const s = { fill: 'none', stroke: '#29B5E8', strokeWidth: 1.6, strokeLinecap: 'round' } as const;
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" style={{ flexShrink: 0, display: 'block' }}>
      <path d="M7 1.2v11.6M1.98 4.1l10.04 5.8M1.98 9.9l10.04-5.8" {...s} />
      <path d="M5.6 2.2 7 3.4l1.4-1.2M5.6 11.8 7 10.6l1.4 1.2" {...s} />
    </svg>
  );
}

/** NetSuite, drawn as a bold N. */
export function NetSuiteMark() {
  return <div style={geist(11, 12, '#1F4E79', 700)}>N</div>;
}

/* -------------------------------------------------------------- buttons */

/** The near-black button with a trailing arrow. */
export function DarkButton({ label, style }: { label: string; style?: CSSProperties }) {
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 8,
        padding: '10px 12px 10px 16px',
        borderRadius: 10,
        backgroundColor: C.ink,
        ...style,
      }}
    >
      <div style={geist(14, 18, '#FFFFFF', 500, { width: 'max-content' })}>{label}</div>
      <ArrowRight />
    </div>
  );
}

/* ------------------------------------------------------------- signals */

/** Three rising bars and the fit label: "Strong fit · 4 signals". */
export function FitSignal({ strong, label }: { strong: boolean; label: string }) {
  const on = strong ? '#16A34A' : C.slateDark;
  const bars = [
    { h: 6, c: on },
    { h: 9, c: on },
    { h: 12, c: strong ? on : '#D9D4CF' },
  ];
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
      <div style={{ display: 'flex', alignItems: 'flex-end', gap: 2 }}>
        {bars.map((b, i) => (
          <div key={i} style={{ flexShrink: 0, width: 3, height: b.h, borderRadius: 1, backgroundColor: b.c }} />
        ))}
      </div>
      <div style={geist(13, 18, strong ? '#15803D' : C.slateDark, 500)}>{label}</div>
    </div>
  );
}

/* ---------------------------------------------------------------- note */

/**
 * "This is an outside read": the film-backed note that opens both screens.
 * The two screens space it slightly differently in Paper, and name different
 * tools, so both are props.
 */
export function OutsideNote({
  padding,
  copyGap,
  logos,
}: {
  padding: string;
  copyGap: number;
  logos: ReactNode;
}) {
  return (
    <div
      style={{
        position: 'relative',
        boxSizing: 'border-box',
        width: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: 40,
        padding,
        overflow: 'clip',
        borderRadius: 16,
        border: `1px solid ${C.line}`,
        backgroundColor: C.well,
      }}
    >
      <Film position="50% 40%" shade={SHADE_NOTE} />
      <div style={{ position: 'relative', display: 'flex', flexDirection: 'column', gap: copyGap, maxWidth: 640 }}>
        <div style={geist(18, 26, C.ink, 500, { letterSpacing: '-0.01em' })}>This is an outside read</div>
        <div style={interText(14, 22, C.slateDark)}>
          We only read what Tessaro makes public, so every number is a range. Connect your tools and Vantage
          measures the real ones.
        </div>
      </div>
      <div style={{ position: 'relative', flexShrink: 0, display: 'flex', alignItems: 'center', gap: 16 }}>
        <div style={{ display: 'flex', gap: 4 }}>{logos}</div>
        <DarkButton label="Connect tools, read only" />
      </div>
    </div>
  );
}

